D={
82175:("Phrasal verbs de movimento","**Get in/out** (carro, táxi); **get on/off** (ônibus, trem, avião); **pull over**; **set off**.",[("Please {{get in}} the car.","Entre no carro, por favor."),("I'll {{get on}} the bus.","Vou subir no ônibus."),("I'll {{get off}} at Central Station.","Descerei na Central."),("We {{set off}} at dawn.","Partimos ao amanhecer.")],"Qual combina com “bus”?",["get in","get on","get at"],1,"Get on the bus."),
82176:("look up / look after","**Look up** = procurar numa fonte; **look after** = cuidar; **look out** = cuidado; **look forward to + -ing**.",[("I {{look up}} new words.","Procuro palavras novas."),("She {{looks after}} the pig.","Ela cuida do porco."),("{{Look out}}! A car is coming.","Cuidado! Vem um carro."),("I {{look forward to}} seeing you.","Espero ver você.")],"“Look after” significa…",["procurar","cuidar","admirar"],1,"Cuidar."),
82177:("take off / take up","**Take off** = decolar/tirar; **take up** = começar um hobby; **take over** = assumir; **take after** = puxar a.",[("The plane will {{take off}} in ten minutes.","O avião decola em dez minutos."),("I want to {{take up}} guitar.","Quero começar a tocar violão."),("He {{takes after}} his father.","Ele puxou o pai."),("She'll {{take over}} next month.","Ela assume mês que vem.")],"“Take after” significa…",["parecer-se com um parente","decolar","devolver"],0,"Puxar a."),
930039:("keep a secret","**Keep** combina com *a secret, in touch, calm, an eye on*.",[("Can you {{keep a secret}} for me?","Você guarda um segredo para mim?"),("Let's {{keep in touch}} by text.","Vamos manter contato por mensagem."),("{{Keep calm}}!","Mantenha a calma!"),("{{Keep an eye on}} the kids.","Fique de olho nas crianças.")],"Qual está certa?",["hold a secret","keep a secret","stay a secret"],1,"Keep a secret."),
82178:("give up / give in","**Give up** = desistir; **give in** = ceder; **give away** = doar/revelar; **give back**; **give out**.",[("Never {{give up}} on your dreams.","Nunca desista dos seus sonhos."),("She finally {{gave in}} to the pressure.","Ela finalmente cedeu à pressão."),("They {{give away}} old clothes.","Eles doam roupas velhas."),("{{Give back}} my pen.","Devolva minha caneta.")],"“Give in” significa…",["ceder","dar","entrar"],0,"Ceder."),
82179:("put up with / put off","**Put up with** = aguentar; **put off** = adiar; **put out** = apagar; **put away** = guardar.",[("I can't {{put up with}} this noise.","Não aguento este barulho."),("Don't {{put off}} your homework.","Não adie sua lição."),("The firefighter {{put out}} the fire.","O bombeiro apagou o fogo."),("{{Put away}} your toys.","Guarde seus brinquedos.")],"“Put off” significa…",["adiar","apagar","vestir"],0,"Adiar."),
82180:("come across / come up with","**Come across** = encontrar por acaso; **come up with** = ter uma ideia; **come down with** = pegar uma doença.",[("I {{came across}} an old photo.","Encontrei uma foto antiga por acaso."),("She {{came up with}} a brilliant idea.","Ela teve uma ideia brilhante."),("He {{came down with}} the flu.","Ele pegou gripe."),("{{Come on}}! Let's go.","Vamos! Bora.")],"“Come up with” significa…",["ter uma ideia","subir","aparecer"],0,"Bolar."),
82181:("go on / go through","**Go on** = continuar; **go through** = passar por; **go over** = revisar; **go ahead** = em frente.",[("Please {{go on}} with your story.","Continue sua história, por favor."),("He had to {{go through}} hard times.","Ele passou por tempos difíceis."),("Let's {{go over}} the plan.","Vamos revisar o plano."),("{{Go ahead}}, ask.","Pode perguntar.")],"“Go over” significa…",["revisar","atravessar","ir embora"],0,"Revisar."),
82182:("run out of","**Run out of + nome** = ficar sem; **run into** = encontrar sem querer; **running low** = quase acabando.",[("We {{run out of}} milk every week.","Ficamos sem leite toda semana."),("I {{ran into}} an old friend.","Esbarrei num velho amigo."),("The battery is {{running low}}.","A bateria está acabando."),("We've {{used up}} all the flour.","Gastamos toda a farinha.")],"Qual está certa?",["We ran out milk.","We ran out of milk.","We ran of milk."],1,"Run out of."),
930040:("hit me up","**Hit me up** = me chame; **text me** = mande mensagem; **chill** = relaxar; **legit** = de verdade.",[("{{Hit me up}} tonight.","Me chame hoje à noite."),("{{Text me}} when you arrive.","Mande mensagem quando chegar."),("Let's {{chill}} at the mall.","Vamos relaxar no shopping."),("That's {{legit}}!","Isso é de verdade!")],"“Hit me up” significa…",["me bata","me chame","me ligue de volta"],1,"Me procure."),
82183:("turn up / turn down","**Turn up** = aparecer/aumentar; **turn down** = recusar/baixar; **turn into** = virar.",[("He didn't {{turn up}} at the party.","Ele não apareceu na festa."),("She had to {{turn down}} the job.","Ela teve de recusar o emprego."),("Gregor {{turned into}} an insect.","Gregor virou um inseto."),("{{Turn down}} the music.","Abaixe a música.")],"“Turn down the offer” =",["aceitar","recusar","aumentar"],1,"Recusar."),
82184:("break down / break up","**Break down** = quebrar/desabar; **break up** = terminar; **break into** = invadir; **break out** = eclodir/fugir.",[("My car will {{break down}} on the road.","Meu carro vai quebrar na estrada."),("They decided to {{break up}} last year.","Eles decidiram terminar ano passado."),("A thief tried to {{break into}} the house.","Um ladrão tentou invadir a casa."),("War {{broke out}} in 1914.","A guerra eclodiu em 1914.")],"“Break up” (casal) = …",["terminar","casar","reconciliar"],0,"Terminar."),
82185:("set up / sort out","**Set up** = montar/criar; **sort out** = resolver; **figure out** = descobrir; **work out**; **carry out**; **find out**.",[("He wants to {{set up}} a new company.","Ele quer abrir uma empresa nova."),("We need to {{sort out}} this problem.","Precisamos resolver este problema."),("I can't {{figure out}} the answer.","Não consigo descobrir a resposta."),("Let's {{find out}} the truth.","Vamos descobrir a verdade.")],"“Sort out” significa…",["organizar/resolver","separar","sair"],0,"Resolver."),
82186:("bring up / bring about","**Bring up** = criar filhos/levantar assunto; **bring back**; **bring about** = provocar.",[("She wants to {{bring up}} her children well.","Ela quer criar bem os filhos."),("Please {{bring back}} my umbrella.","Traga de volta meu guarda-chuva."),("The law will {{bring about}} change.","A lei vai provocar mudança."),("I was {{brought up}} by my grandparents.","Fui criado pelos meus avós.")],"“Bring about” significa…",["provocar","trazer","criar"],0,"Provocar."),
82187:("Phrasal verbs no trabalho","**Call off, carry on, get back to, set up, hand in, follow up**.",[("They had to {{call off}} the meeting.","Tiveram de cancelar a reunião."),("Please {{carry on}} with your work.","Continue o seu trabalho."),("I'll {{get back to}} you tomorrow.","Respondo a você amanhã."),("Please {{hand in}} the report.","Entregue o relatório.")],"“Hand in” significa…",["entregar","dar a mão","atrasar"],0,"Entregar."),
930041:("stand out / stand up for","**Stand out** = se destacar; **stand up for** = defender; **stand by** = apoiar; **stand for** = representar.",[("You {{stand out}} in a crowd.","Você se destaca na multidão."),("{{Stand up for}} your friends.","Defenda seus amigos."),("What does this {{stand for}}?","O que isto representa?"),("I'll {{stand by}} you.","Estarei ao seu lado.")],"“Stand up for” significa…",["defender","levantar","aguentar"],0,"Defender."),
82188:("hang out / catch up","**Hang out** = passar tempo; **catch up** = pôr a conversa em dia; **get along** = se dar bem; **drop by**; **cheer up**.",[("We like to {{hang out}} at the café.","Gostamos de passar tempo no café."),("Let's {{catch up}} over coffee.","Vamos pôr a conversa em dia tomando café."),("Do you {{get along}} with her?","Você se dá bem com ela?"),("{{Cheer up}}!","Anime-se!")],"“Catch up” significa…",["pôr em dia","pegar","correr"],0,"Pôr em dia."),
82189:("Separáveis","Phrasal verbs separáveis: nome no meio ou no fim; **pronome sempre no meio**.",[("{{Pick}} them {{up}}.","Pegue-os."),("Please {{turn}} it {{off}}.","Desligue, por favor."),("Please {{pick up}} the cups.","Pegue os copos, por favor."),("Please {{pick}} the cups {{up}}.","Pegue os copos, por favor.")],"Qual está certa?",["pick up it","pick it up","pick up him"],1,"Pronome no meio."),
82190:("Verbos de três palavras","**Look up to, get on with, keep up with, look forward to, run out of, put up with** não se separam.",[("I {{look up to}} my father.","Admiro meu pai."),("She doesn't {{get on with}} him.","Ela não se dá bem com ele."),("I can't {{keep up with}} you.","Não consigo acompanhar você."),("I can't {{put up with}} it.","Não aguento isso.")],"“Look up to” significa…",["admirar","olhar para cima","procurar"],0,"Admirar."),
82191:("Idioms com animais","**Night owl**, **busy as a bee**, **cat nap**, **eager beaver**, **black sheep**.",[("I'm a {{night owl}}.","Sou noturno."),("She is {{busy as a bee}}.","Ela está superocupada."),("He's the {{black sheep}} of the family.","Ele é a ovelha negra da família."),("I took a {{cat nap}}.","Tirei um cochilo.")],"“Black sheep” é…",["ovelha negra","ovelha preta","cordeiro"],0,"Membro diferente da família."),
82192:("Idioms com cores","**Feeling blue** = triste; **green with envy**; **once in a blue moon** = raramente; **red tape** = burocracia; **white lie**.",[("I'm {{feeling blue}} today.","Estou triste hoje."),("She was {{green with envy}}.","Ela estava morrendo de inveja."),("We meet {{once in a blue moon}}.","Nos vemos raramente."),("It's a {{white lie}}.","É uma mentirinha.")],"“Red tape” significa…",["burocracia","fita vermelha","perigo"],0,"Burocracia."),
930042:("bite the bullet","**Bite the bullet** = enfrentar o difícil; **face the music** = assumir consequências; **hang in there** = não desistir.",[("Just {{bite the bullet}} and call him.","Enfrente e ligue para ele."),("You must {{face the music}} today.","Você deve assumir as consequências hoje."),("{{Hang in there}}!","Aguente firme!"),("She {{took it on the chin}}.","Ela encarou numa boa.")],"“Hang in there” significa…",["aguente firme","pendure","fique em casa"],0,"Não desista."),
82193:("Idioms sobre tempo","**Time flies, about time, better late than never, in no time, on time × in time, time off**.",[("Wow, {{time flies}}!","Uau, o tempo voa!"),("{{It's about time}} you called me.","Já era hora de você me ligar."),("The train arrived {{on time}}.","O trem chegou no horário."),("{{Better late than never}}.","Antes tarde do que nunca.")],"“On time” significa…",["no horário","a tempo","atrasado"],0,"Pontual."),
82194:("Idioms sobre dinheiro","**Broke** = sem dinheiro; **bargain** = pechincha; **cost an arm and a leg**; **every penny counts**.",[("Sorry, I'm {{broke}} this month.","Desculpe, estou sem dinheiro este mês."),("This jacket is a real {{bargain}}.","Esta jaqueta é uma pechincha."),("That phone {{costs an arm and a leg}}.","Aquele celular custa os olhos da cara."),("{{Every penny counts}}.","Cada centavo conta.")],"“Cost an arm and a leg” significa…",["ser muito caro","machucar","ser grátis"],0,"Muito caro."),
82195:("Expressões do dia a dia","**I'm all ears, call it a day, ring a bell, a piece of cake, hit the road, break a leg**.",[("Go ahead, {{I'm all ears}}.","Pode falar, sou todo ouvidos."),("It's late. Let's {{call it a day}}.","É tarde. Vamos encerrar por hoje."),("That name doesn't {{ring a bell}}.","Esse nome não me é familiar."),("{{Break a leg}}!","Boa sorte!")],"“Ring a bell” significa…",["soar familiar","tocar sino","ligar"],0,"Soar familiar."),
82196:("Gírias comuns","**Awesome, stoked, beat, chill, cool, dude** são informais — use com amigos.",[("That concert was {{awesome}}.","Aquele show foi incrível."),("I'm so {{stoked}} about the trip.","Estou muito animado com a viagem."),("I'm {{beat}} after the long day.","Estou exausto depois do dia longo."),("Let's {{chill}}.","Vamos relaxar.")],"Onde NÃO usar gírias?",["e-mail formal","conversa entre amigos","mensagem de texto"],0,"Registro formal."),
82197:("Dar opinião","**In my opinion… I think… I believe… Personally… It seems to me that…** Justifique com *because*.",[("{{In my opinion}}, he is innocent.","Na minha opinião, ele é inocente."),("{{I believe}} he is telling the truth.","Acredito que ele diz a verdade."),("{{Personally}}, I prefer the first one.","Pessoalmente, prefiro o primeiro."),("{{It seems to me that}} it's fair.","Parece-me que é justo.")],"Qual abre uma opinião?",["In my opinion","By the way","Anyway"],0,"In my opinion."),
930043:("also / besides / moreover","**Also, besides** somam; **moreover, in addition, furthermore** são mais formais; **as well as** liga duas coisas.",[("He is {{also}} reliable.","Ele também é confiável."),("{{Moreover}}, he finished early.","Além disso, ele terminou cedo."),("He writes {{as well as}} speaks.","Ele escreve e também fala."),("{{In addition}}, he is polite.","Além disso, é educado.")],"Qual é mais formal?",["also","moreover","too"],1,"Moreover."),
82198:("Concordar","**I agree, you're right, exactly, absolutely, that's true, so do I**.",[("{{I agree}} with you completely.","Concordo totalmente com você."),("{{Exactly}}! That's what I think.","Exatamente! É o que penso."),("{{You're right}} about that.","Você tem razão nisso."),("{{Absolutely}}!","Absolutamente!")],"Qual NÃO concorda?",["Exactly!","I disagree.","That's true."],1,"Disagree."),
82199:("Discordar com educação","**I see your point, but… I'm afraid I disagree… I respect your opinion, but…**",[("{{I see your point, but}} I think differently.","Entendo seu ponto, mas penso diferente."),("{{I'm afraid I disagree}}.","Receio discordar."),("{{I respect your opinion, but}} I'm not sure.","Respeito sua opinião, mas não tenho certeza."),("{{I'm not sure I agree}}.","Não tenho certeza se concordo.")],"Qual discorda com educação?",["You're wrong!","I see your point, but I disagree.","No."],1,"Suavizado."),
82200:("Prós e contras","**On the one hand… on the other hand… One advantage… a disadvantage… the downside… In conclusion…**",[("{{On the one hand}}, it's cheap.","Por um lado, é barato."),("{{On the other hand}}, it's far.","Por outro lado, é longe."),("{{The downside}} is the noise.","A desvantagem é o barulho."),("{{In conclusion}}, I'd choose it.","Em conclusão, eu escolheria.")],"“The downside” significa…",["a vantagem","a desvantagem","a descida"],1,"Desvantagem."),
82201:("because × that's why","**Because** + razão; **that's why** = por isso (resultado).",[("I think so {{because}} the evidence is weak.","Penso assim porque a evidência é fraca."),("The evidence is weak, {{that's why}} I disagree.","A evidência é fraca, por isso discordo."),("{{What's your reason}}?","Qual é seu motivo?"),("That's {{why}} I came.","Por isso vim.")],"“That's why” introduz…",["o motivo","o resultado","o tempo"],1,"Resultado."),
82202:("Pedir opinião","**What do you think about…? How do you feel about…? What's your opinion on…?**",[("{{What do you think about}} this plan?","O que você acha deste plano?"),("{{How do you feel about}} moving?","Como você se sente sobre mudar?"),("{{What's your opinion about}} the film?","Qual é a sua opinião sobre o filme?"),("{{Do you agree}}?","Você concorda?")],"Qual pede opinião?",["What do you think?","Where do you live?","When is it?"],0,"What do you think?"),
930044:("throw away / throw up","**Throw away / out** = descartar; **throw up** = vomitar; **throw together** = improvisar.",[("{{Throw away}} old clothes.","Descarte roupas velhas."),("I feel like I'll {{throw up}}.","Sinto que vou vomitar."),("Let me {{throw together}} a salad.","Deixe-me improvisar uma salada."),("{{Throw out}} the rubbish.","Jogue o lixo fora.")],"“Throw together” significa…",["improvisar","atirar junto","jogar"],0,"Improvisar."),
81046:("Question tags","Confirme com a **tag** no fim: *It is cold, isn't it?* Mesmo auxiliar, invertido.",[("It is cold, {{isn't it}}?","Está frio, não está?"),("You like coffee, {{don't you}}?","Você gosta de café, não gosta?"),("You are tired, {{aren't you}}?","Você está cansado, não está?"),("She can swim, {{can't she}}?","Ela sabe nadar, não sabe?")],"Complete: “He works here, ___?”",["isn't he","doesn't he","does he"],1,"Presente afirmativo: doesn't he."),
82203:("Debater tecnologia","**On the one hand… On the other hand… The main risk is… One benefit is… depend on, worry about**.",[("Many people {{depend on}} technology.","Muita gente depende da tecnologia."),("I {{worry about}} my privacy.","Preocupo-me com minha privacidade."),("{{The main risk}} is losing our data.","O principal risco é perder nossos dados."),("{{One benefit}} is speed.","Um benefício é a rapidez.")],"Qual está certa?",["depend of","depend on","depend in"],1,"Depend on."),
82204:("Questões sociais","**I think it's (not) fair that… People deserve… The gap between… Governments should…**",[("Everyone {{deserves}} a fair chance.","Todos merecem uma chance justa."),("The gap between rich and poor {{is growing}}.","A diferença entre ricos e pobres cresce."),("I {{don't think it's fair}}.","Não acho justo."),("Governments {{should}} help.","Os governos deveriam ajudar.")],"“Deserve” significa…",["merecer","servir","desejar"],0,"Merecer."),
82205:("Persuadir","**Why don't you…? You should… You'll regret it if… I'm sure you'll…**",[("{{Why don't you}} try it once?","Por que você não tenta uma vez?"),("{{You'll regret it if}} you don't go.","Você vai se arrepender se não for."),("{{I'm sure you'll}} like it.","Tenho certeza de que você vai gostar."),("{{I believe you can do it}}.","Acredito que você consegue.")],"“You'll regret it” é…",["um incentivo","um adeus","uma pergunta"],0,"Persuasão."),
82206:("Compromisso","**Let's compromise. We can meet halfway. I'm willing to… Do we have a deal?**",[("{{Let's compromise}} on the price.","Vamos chegar a um acordo no preço."),("We can {{meet halfway}}.","Podemos nos encontrar no meio-termo."),("{{I'm willing to}} wait a little.","Estou disposto a esperar um pouco."),("{{Do we have a deal}}?","Temos um acordo?")],"Qual aceita o acordo?",["That sounds fair.","No deal.","Never."],0,"Aceita."),
930045:("collocations com run","**Run a business**, **run out of**, **run errands**, **run into**.",[("I {{run a business}} from home.","Administro um negócio de casa."),("We {{ran out of}} time.","Ficamos sem tempo."),("I {{run errands}} on Saturday.","Faço pequenas tarefas aos sábados."),("I {{ran into}} her yesterday.","Esbarrei nela ontem.")],"“Run errands” significa…",["correr","fazer pequenas tarefas","errar"],1,"Fazer recados."),
82207:("Do you mean…?","Para confirmar: **Do you mean…?** Para pedir outra explicação: **What do you mean?**",[("{{Which}} version of the story is true?","Qual versão da história é verdadeira?"),("{{Do you mean}} the first story?","Você quer dizer a primeira história?"),("{{Could you repeat that}}, please?","Poderia repetir, por favor?"),("{{What do you mean}}?","O que você quer dizer?")],"“Do you mean…?” serve para…",["confirmar","negar","terminar"],0,"Confirmar."),
82208:("Interromper com educação","**Sorry to interrupt, but… May I add something?** Depois: *Please, go on.*",[("{{Sorry to interrupt, but}} I have a question.","Desculpe interromper, mas tenho uma pergunta."),("{{May I add something}}?","Posso acrescentar algo?"),("{{Please, go on}}.","Por favor, continue."),("In my opinion, we should wait.","Na minha opinião, devemos esperar.")],"Qual interrompe com educação?",["Shut up!","Sorry to interrupt, but…","Wait!"],1,"Sorry to interrupt."),
82209:("by the way / anyway / speaking of","**By the way** = a propósito; **anyway** = voltar/fechar; **speaking of** = falando em.",[("{{By the way}}, did you see the game?","A propósito, você viu o jogo?"),("{{Speaking of}} music, do you play guitar?","Falando em música, você toca violão?"),("{{Anyway}}, don't forget to call her.","Enfim, não esqueça de ligar para ela."),("{{By the way}}, it's late.","A propósito, é tarde.")],"“Speaking of” conecta com…",["o que foi dito","o futuro","uma ordem"],0,"O que foi dito."),
82210:("Mostrar interesse","**Really? I see. That sounds interesting.** Depois faça perguntas.",[("{{Really}}? And what happened next?","Sério? E o que aconteceu depois?"),("{{That sounds interesting}}.","Parece interessante."),("{{Please tell me more}} about it.","Conte-me mais sobre isso."),("{{I see}}.","Entendo.")],"Qual mostra interesse?",["Really? Tell me more.","Whatever.","Okay."],0,"Pergunta."),
930046:("Combinar por telefone","**How about… That works for me. I'm afraid I can't. Let's reschedule.**",[("{{How about}} eleven o'clock?","Que tal às onze?"),("{{That works for me}}.","Para mim está bom."),("{{I'm afraid I can't}}.","Receio que não possa."),("{{Let's reschedule}} for Monday.","Vamos remarcar para segunda.")],"“Reschedule” significa…",["remarcar","cancelar","chegar cedo"],0,"Remarcar."),
82211:("Ganhar tempo","**Well, let me see… How can I put it? I'm not sure.**",[("{{Well, let me see}}.","Bem, deixe-me ver."),("{{I'm not sure}} yet.","Ainda não tenho certeza."),("{{How can I put it}}?","Como posso dizer?"),("{{I can't decide}} right now.","Não consigo decidir agora.")],"Para que servem essas pausas?",["Pensar sem silêncio","Terminar a conversa","Recusar"],0,"Evitam silêncio."),
82212:("Resumir","**To sum up…** (resumindo) e **In conclusion…** (em conclusão). **All in all / overall** = no geral.",[("{{To sum up}}, we agree on three points.","Resumindo, concordamos em três pontos."),("{{In conclusion}}, the plan is clear.","Em conclusão, o plano é claro."),("{{Overall}}, it went well.","No geral, foi bem."),("{{All in all}}, I agree.","No geral, concordo.")],"“Overall” significa…",["no geral","às vezes","nunca"],0,"No geral."),
82213:("Carta de apresentação","**Dear Sir or Madam**, *I am writing to apply for…*, **I look forward to hearing from you. Yours faithfully**.",[("{{Dear Sir or Madam}},","Prezado(a) senhor(a),"),("{{I am writing to apply}} for the position.","Escrevo para me candidatar à vaga."),("I have two years of {{experience}} in sales.","Tenho dois anos de experiência em vendas."),("{{I look forward to hearing from you}}.","Aguardo seu retorno.")],"Como fechar uma carta formal?",["Yours faithfully","See you","Bye"],0,"Yours faithfully."),
82214:("Entrevista","**My biggest strength is… My weakness is…, but I'm improving.** Dê um exemplo.",[("{{My biggest strength is}} teamwork.","Meu maior ponto forte é o trabalho em equipe."),("{{Can you describe}} yourself?","Pode se descrever?"),("{{Let me give you an example}}.","Deixe-me dar um exemplo."),("My weakness is time, {{but I'm improving}}.","Meu ponto fraco é o tempo, mas estou melhorando.")],"“Strength” significa…",["ponto forte","força física","fraqueza"],0,"Ponto forte."),
82215:("Negociar salário","Use **could / would**: *Could we talk about the salary? I would like to ask for…*",[("{{Could we talk about}} the salary?","Poderíamos falar do salário?"),("{{I would like to ask for}} a raise.","Gostaria de pedir um aumento."),("That is a {{fair}} price.","É um preço justo."),("What about the {{benefits}}?","E os benefícios?")],"Qual é mais educado?",["I want more money.","Could we talk about the salary?","Pay me more."],1,"Could we talk."),
930047:("Esportes","**Win / lose (lost) / draw / compete / score**.",[("We {{compete}} in the league.","Competimos na liga."),("We {{won}} by one point.","Ganhamos por um ponto."),("{{What's the score}}?","Qual é o placar?"),("They {{lost}} the match.","Eles perderam a partida.")],"Qual é o passado de “lose”?",["losed","lost","loss"],1,"Lose → lost."),
82216:("present perfect no trabalho","**Have/has + particípio**; **just** (recente), **already** (feito antes).",[("I've {{just}} started a new job.","Acabei de começar um emprego novo."),("She has {{already}} learned the system.","Ela já aprendeu o sistema."),("Everyone here {{has been}} kind.","Todos aqui têm sido gentis."),("I've {{met}} my team.","Conheci minha equipe.")],"“Just” indica…",["algo muito recente","algo antigo","algo futuro"],0,"Recente."),
82217:("Falar de um problema","**I'd like to raise a concern.** Depois sugira: **Could we schedule a meeting? Let's sort this out.**",[("{{I'd like to raise a concern}}.","Gostaria de levantar uma preocupação."),("{{Could we schedule}} a meeting?","Poderíamos marcar uma reunião?"),("{{Let's find a solution}}.","Vamos achar uma solução."),("{{Let's sort this out}}.","Vamos resolver isto.")],"Qual abre um problema sem brigar?",["You're wrong!","I'd like to raise a concern.","This is bad."],1,"Raise a concern."),
82218:("Apresentação","Guie a plateia: **Today I'm going to talk about… First… Next… Finally… Thank you. Any questions?**",[("{{Today I'm going to talk about}} clean energy.","Hoje vou falar sobre energia limpa."),("{{First}}, let me show you this slide.","Primeiro, deixe-me mostrar este slide."),("{{Finally}}, thank you for listening.","Por fim, obrigado por ouvirem."),("{{Any questions}}?","Alguma pergunta?")],"Qual abre a apresentação?",["Today I'm going to talk about…","Thank you.","Any questions?"],0,"Abertura."),
82219:("Reunião","**Let's get started.** *I'd like to suggest…* **Let's wrap up. To sum up, we decided…**",[("{{Let's get started}}.","Vamos começar."),("{{I'd like to suggest}} another time.","Gostaria de sugerir outro horário."),("{{We need to make a decision}}.","Precisamos tomar uma decisão."),("{{Let's wrap up}}.","Vamos encerrar.")],"“Wrap up” significa…",["encerrar","embrulhar","começar"],0,"Encerrar."),
82220:("Prazos e atrasos","Avise o atraso: **We will be late with…** Desculpe-se: **I apologize for the delay.** Dê nova data.",[("{{We will be late}} with the report.","Vamos atrasar o relatório."),("{{I apologize for the delay}}.","Peço desculpas pelo atraso."),("{{I promise to send it}} on Monday.","Prometo enviar na segunda."),("The deadline {{is}} Friday.","O prazo é sexta.")],"Qual pede desculpas?",["I apologize for the delay.","It's your fault.","Whatever."],0,"Apologize."),
930048:("try on / try out","**Try on** = experimentar roupa; **try out** = testar; **try for** = tentar conseguir.",[("Can I {{try on}} these shoes?","Posso experimentar estes sapatos?"),("I want to {{try out}} a new app.","Quero testar um aplicativo novo."),("I'll {{try for}} the job.","Vou tentar a vaga."),("{{Try again}}!","Tente de novo!")],"“Try on” é usado com…",["roupas","comida","mensagens"],0,"Roupas."),
82221:("E-mail profissional","Formal: **Dear Mr Lopes… Best regards**. Informal: **Hi Sam… Thanks!** *Following up on…* e *Please find attached…*",[("I'm {{following up on}} my last message.","Estou retomando minha última mensagem."),("{{Please find}} the invoice {{attached}}.","Segue a fatura em anexo."),("{{Thank you for your quick reply}}.","Obrigado pela resposta rápida."),("{{Best regards}}, Ana","Atenciosamente, Ana")],"“Please find attached” avisa…",["um anexo","um erro","um atraso"],0,"Anexo."),
82222:("Trabalho em equipe","**Let's divide the work. You're in charge of… Good job! Could you give me a hand?**",[("{{Let's divide}} the work.","Vamos dividir o trabalho."),("{{I'm in charge of}} the budget.","Sou responsável pelo orçamento."),("{{Could you give me a hand}}?","Pode me dar uma mão?"),("{{Good job}}!","Bom trabalho!")],"“Give me a hand” significa…",["me ajudar","me dar a mão","me pagar"],0,"Ajudar."),
82223:("Carreira","Passado: **I was promoted. He was laid off.** Planos: **I'm thinking of changing jobs. I'd like to…** Valores: *work-life balance*.",[("I {{was promoted}} last year.","Fui promovido ano passado."),("I'm {{thinking of changing}} jobs.","Estou pensando em mudar de emprego."),("I need a good {{work-life balance}}.","Preciso de bom equilíbrio entre trabalho e vida."),("He {{was laid off}}.","Ele foi demitido.")],"“Laid off” significa…",["demitido por corte","promovido","contratado"],0,"Demissão."),
}
